# export_car.py — Blender (headless) exporter: glTF car -> "RCP2" mesh pack (car.bin) for carpack.as.
#
#   blender -b --factory-startup -P tools/export_car.py -- <CarConcept.gltf> car.bin [--ao SAMPLES] [--scale S]
#
# Source: the Khronos glTF Sample Assets "CarConcept" (CC BY 4.0, Eric Chadwick / Darmstadt Graphics Group,
# from a CC0 model by Unity Fan). See README.md > Credits. No source textures are used: every material is
# shaded by name in world.as matFor(), and the plate texture is generated by tools/make_plate.py.
#
# Pack layout (read by carpack.as):
#   header  "RCP2", mesh count u32, half extents f32x3, 3 x f32 spare, wheel count u32 + 3 spare u32,
#           then per wheel: pivot f32x3 + radius f32
#   mesh    name char[32], part u32 (0 body, 1..4 wheels FL FR RL RR), vertex count u32, index count u32,
#           spare u32, uv range f32x4 (u0, v0, u1, v1), vertices, u32 indices
#   vertex  20 bytes: pos snorm16x4 (pack half extents), normal octahedral snorm16x2,
#           uv unorm16x2 (per-mesh uv range), ao + 3 spare unorm8x4
# Output frame: metres, +y up, +z forward (nose), +x = the car's left, ground at y = 0, centred in x and z.
# Meshes are merged per (renderer material, part). Wheel parts get a "W_" prefix and spin.
import bpy, sys, struct, json
import numpy as np
from mathutils import Matrix, Vector

argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
SRC = argv[0]
OUT = argv[1] if len(argv) > 1 else "car.bin"
AO_SAMPLES = int(argv[argv.index("--ao") + 1]) if "--ao" in argv else 0
S = float(argv[argv.index("--scale") + 1]) if "--scale" in argv else 1.0

# source material -> renderer material (world.as matFor)
MATS = {
    "Paint 1 Carmine": "CarPaint",
    "Paint 2 Carmine": "MetallicBlack02",   # the model's second colour: roof, sills, mirror caps, cowl
    "Glass": "GlassBlack",
    "Material_2": "Rubber",                  # gaskets, wipers, cage, frames
    "Mechanical": "BottomCar",
    "Interior 1": "Interior",
    "Interior 2": "Interior",
    "Floormat": "Interior",
    "Panel Sides": "Interior",
    "Dashboard": "Interior",
    "Interior 3 Carmine": "InteriorAccent",
    "Hardware": "MetallicGray",
    "License": "NumberPlate",
    "Signallight": "GlassAmber",
    "Brakelight": "LightRed",
    "Headlight": "Light",
    "Mirror": "Mirror",
    "Brake": "Caliper",
    "Disc": "Disc",
    "Tireside": "TireColor",
    "Tiretread": "TireColor",
    "Rim1": "MetallicBlack02",
    "Rim2": "WheelFace",
}

bpy.ops.wm.read_factory_settings(use_empty=True)
bpy.ops.import_scene.gltf(filepath=SRC)
scene = bpy.context.scene
meshes = [o for o in scene.objects if o.type == "MESH"]
print("mesh objects", len(meshes))


def mats_of(o):
    return [s.material.name if s.material else "Material_2" for s in o.material_slots] or ["Material_2"]


def wverts(o):
    me = o.data
    co = np.empty(len(me.vertices) * 3, np.float64)
    me.vertices.foreach_get("co", co)
    M = np.array(o.matrix_world, dtype=np.float64)
    return co.reshape(-1, 3) @ M[:3, :3].T + M[:3, 3]


unknown = sorted({m for o in meshes for m in mats_of(o) if m not in MATS})
assert not unknown, unknown

# ---------------------------------------------------------------- wheels
# The source poses the front wheels steered. Square every wheel up: the tyre's axle is its thinnest axis
# (PCA), and the whole wheel group (tyre, rim, disc, caliper) is turned about the tyre centre so the axle
# lies along x.
WHEELS = {"WheelFrontR": 1, "WheelFrontL": 2, "WheelRearR": 3, "WheelRearL": 4}   # glTF R = output -x
wheel_of_obj = {}
corners = {}
for root, part in WHEELS.items():
    e = bpy.data.objects[root]
    kids = [o for o in meshes if o.parent == e]
    tyre = [o for o in kids if "Tiretread" in mats_of(o)]
    assert len(tyre) == 1, (root, [o.name for o in kids])
    P = wverts(tyre[0])
    c = (P.min(axis=0) + P.max(axis=0)) / 2
    w, V = np.linalg.eigh(np.cov((P - c).T))
    axle = V[:, 0] * (1 if V[0, 0] > 0 else -1)
    R = Vector(axle).rotation_difference(Vector((1, 0, 0))).to_matrix().to_4x4()
    T = Matrix.Translation(Vector(c)) @ R @ Matrix.Translation(Vector(-c))
    for o in kids:
        o.matrix_world = T @ o.matrix_world
    bpy.context.view_layer.update()
    P = wverts(tyre[0])
    r = (P[:, 2].max() - P[:, 2].min()) / 2
    corners[part] = (c, r)
    print(f"{root}: axle {np.round(axle, 3)} turned {np.degrees(np.arccos(min(1, abs(axle[0])))):.1f} deg, r {r:.3f}, "
          f"width {P[:, 0].max() - P[:, 0].min():.3f}, z {P[:, 2].min():.3f}..{P[:, 2].max():.3f}")
    for o in kids:
        if "Brake" in mats_of(o):
            continue            # calipers stay on the body: they turn with steering, not with the wheel
        wheel_of_obj[o.name] = part

ground = min(c[2] - r for c, r in corners.values())
WHEEL_R = float(np.mean([r for _, r in corners.values()]))
print("wheel radius", WHEEL_R, "ground z", ground)

# ---------------------------------------------------------------- AO bake (optional)
if AO_SAMPLES > 0:
    scene.render.engine = "CYCLES"
    prefs = bpy.context.preferences.addons["cycles"].preferences
    try:
        prefs.compute_device_type = "METAL"
        prefs.get_devices()
        for d in prefs.devices:
            d.use = True
        scene.cycles.device = "GPU"
    except Exception as ex:
        print("GPU setup failed", ex)
    scene.cycles.samples = AO_SAMPLES
    scene.render.bake.target = "VERTEX_COLORS"
    scene.world = scene.world or bpy.data.worlds.new("W")
    scene.world.light_settings.distance = 0.6 / S   # 0.6 m after scaling: crevices and wheel wells
    for o in meshes:
        me = o.data
        if "AO" not in me.color_attributes:
            me.color_attributes.new("AO", "BYTE_COLOR", "CORNER")
        me.color_attributes.active_color = me.color_attributes["AO"]
    bpy.ops.object.select_all(action="DESELECT")
    for o in meshes:
        o.select_set(True)
    bpy.context.view_layer.objects.active = meshes[0]
    print("baking AO ...")
    bpy.ops.object.bake(type="AO", target="VERTEX_COLORS")
    print("AO baked")

# ---------------------------------------------------------------- gather triangles
buckets = {}
for o in meshes:
    me = o.data
    me.calc_loop_triangles()
    nl = len(me.loops)
    M = np.array(o.matrix_world, dtype=np.float64)
    co = wverts(o).astype(np.float32)
    lv = np.empty(nl, np.int32)
    me.loops.foreach_get("vertex_index", lv)
    cn = np.empty(nl * 3, np.float32)
    me.corner_normals.foreach_get("vector", cn)
    cn = cn.reshape(-1, 3) @ np.linalg.inv(M[:3, :3]).T.T
    cn /= np.maximum(np.linalg.norm(cn, axis=1, keepdims=True), 1e-12)
    uv = np.zeros((nl, 2), np.float32)
    if o.name == "License Plate":
        # planar map for the generated plate: u runs right-to-left in x (the plate faces +y, the rear),
        # v top-to-bottom in z
        p = co[lv]
        uv[:, 0] = (p[:, 0].max() - p[:, 0]) / (p[:, 0].max() - p[:, 0].min())
        uv[:, 1] = (p[:, 2] - p[:, 2].min()) / (p[:, 2].max() - p[:, 2].min())
    elif me.uv_layers.active:
        tmp = np.empty(nl * 2, np.float32)
        me.uv_layers.active.data.foreach_get("uv", tmp)
        uv = tmp.reshape(-1, 2)
    ao = np.ones(nl, np.float32)
    if "AO" in me.color_attributes:
        ca = me.color_attributes["AO"]
        tmp = np.empty(len(ca.data) * 4, np.float32)
        ca.data.foreach_get("color", tmp)
        tmp = tmp.reshape(-1, 4)[:, 0]
        ao = tmp if ca.domain == "CORNER" else tmp[lv]
    nt = len(me.loop_triangles)
    tl = np.empty(nt * 3, np.int32)
    me.loop_triangles.foreach_get("loops", tl)
    tl = tl.reshape(-1, 3)
    tm = np.empty(nt, np.int32)
    me.loop_triangles.foreach_get("material_index", tm)
    mats = mats_of(o)
    part = wheel_of_obj.get(o.name, 0)
    for mi in np.unique(tm):
        name = MATS[mats[min(mi, len(mats) - 1)]]
        if part > 0:
            name = "W_" + name
        tri = tl[tm == mi]
        b = buckets.setdefault((name[:31], part), [])
        b.append((co[lv[tri]].reshape(-1, 3), cn[tri].reshape(-1, 3), uv[tri].reshape(-1, 2), ao[tri].reshape(-1)))


# ---------------------------------------------------------------- convert + weld + quantise
def toY(p):
    # Blender (glTF import): +z up, nose at -y, car's left at +x  ->  pack: +y up, nose at +z, left at +x
    return np.stack([p[:, 0], p[:, 2] - ground, -p[:, 1]], axis=1) * S


allp = toY(np.concatenate([np.concatenate([x[0] for x in v]) for v in buckets.values()]))
mn = allp.min(axis=0)
mx = allp.max(axis=0)
centre = np.array([(mn[0] + mx[0]) / 2, 0.0, (mn[2] + mx[2]) / 2], np.float32)
half = np.abs(allp - centre).max(axis=0) * 1.0001
print("bbox", mn - centre, mx - centre, "half", half)


def octenc(n):
    n = n / np.sum(np.abs(n), axis=1, keepdims=True)
    o = n[:, :2].copy()
    neg = n[:, 2] < 0
    sx = np.where(o[neg, 0] >= 0, 1.0, -1.0)
    sy = np.where(o[neg, 1] >= 0, 1.0, -1.0)
    ox = (1 - np.abs(o[neg, 1])) * sx
    oy = (1 - np.abs(o[neg, 0])) * sy
    o[neg, 0] = ox
    o[neg, 1] = oy
    return o


wheel_piv = [None] * 4
for part, (c, r) in corners.items():
    wheel_piv[part - 1] = toY(np.array([c]))[0] - centre

out = bytearray()
records = []
total_v = total_i = 0
for (name, part), lst in sorted(buckets.items()):
    P = toY(np.concatenate([x[0] for x in lst])) - centre
    Nn = np.concatenate([x[1] for x in lst])
    Nn = np.stack([Nn[:, 0], Nn[:, 2], -Nn[:, 1]], axis=1)
    U = np.concatenate([x[2] for x in lst])
    A = np.concatenate([x[3] for x in lst])
    qp = np.clip(np.round(P / half * 32767), -32767, 32767).astype(np.int16)
    qn = np.clip(np.round(octenc(Nn) * 32767), -32767, 32767).astype(np.int16)
    umin = U.min(axis=0)
    umax = U.max(axis=0)
    ur = np.maximum(umax - umin, 1e-6)
    qu = np.clip(np.round((U - umin) / ur * 65535), 0, 65535).astype(np.uint16)
    qa = np.clip(np.round(A * 255), 0, 255).astype(np.uint8)
    rec = np.zeros(len(P), dtype=[("p", "<i2", 4), ("n", "<i2", 2), ("u", "<u2", 2), ("a", "u1", 4)])
    rec["p"][:, :3] = qp
    rec["n"] = qn
    rec["u"] = qu
    rec["a"][:, 0] = qa
    rec["a"][:, 3] = 255
    uniq, inv = np.unique(rec, return_inverse=True)
    idx = inv.astype(np.uint32).reshape(-1)
    nb = name.encode()[:31]
    hdr = struct.pack("<32sIIII4f", nb + b"\0" * (32 - len(nb)), part, len(uniq), len(idx), 0,
                      float(umin[0]), float(umin[1]), float(umax[0]), float(umax[1]))
    out += hdr + uniq.tobytes() + idx.tobytes()
    records.append((name, part, len(uniq), len(idx) // 3))
    total_v += len(uniq)
    total_i += len(idx)

head = struct.pack("<4sI3f3f", b"RCP2", len(records), *[float(x) for x in half], 0.0, 0.0, 0.0)
head += struct.pack("<4I", 4, 0, 0, 0)
for p in wheel_piv:
    head += struct.pack("<4f", float(p[0]), float(p[1]), float(p[2]), WHEEL_R * S)
open(OUT, "wb").write(head + out)
for r in records:
    print("  ", r)
print("wheels", [list(np.round(p, 3)) for p in wheel_piv], "r", WHEEL_R * S)
print("meshes", len(records), "verts", total_v, "tris", total_i // 3, "bytes", len(head) + len(out))
